import{_ as r,l,o as a,c as n,v as t,p as s,x as o,d as E,i as p,S as d}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"蓝牙与 BLE","description":"","frontmatter":{"title":"蓝牙与 BLE","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/bluetooth-ble.md","filePath":"cs/bluetooth-ble.md","lastUpdated":1789023840000}'),c={name:"cs/bluetooth-ble.md"};function h(B,e,T,u,_,A){const i=l("Mermaid");return a(),n("div",null,[e[1]||(e[1]=t('<h1 id="蓝牙与-ble" tabindex="-1">蓝牙与 BLE <a class="header-anchor" href="#蓝牙与-ble" aria-label="Permalink to &quot;蓝牙与 BLE&quot;">​</a></h1><div class="epigraph"><p>经典蓝牙用跳频 piconet 扛 2.4 GHz 干扰；BLE 用短广告与连接间隔换电池寿命，不接以太网 MAC 学习那一套。</p><footer>—— 据 Bluetooth SIG Core Specification；IEEE 802.15.1 历史对照整理</footer></div><p><a href="/cs/wifi6-ofdma">上一课</a> 把 ISM 频段写成宽带调度。键盘、信标、耳机不需要 OFDM 160 MHz。缺口是<strong>个人域网</strong>：经典蓝牙 SCO/ACL 与 BLE 广告、GATT。本课不把蜂窝 RAN 写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>与 AP 争 2.4 GHz：蓝牙跳 79（或 BLE 40）个信道，平均干扰。主从 piconet，不是交换机洪泛。BLE：广播通道发 adv，主机扫描后建立连接，用连接间隔睡觉——容量公式仍成立，但设计目标是 μJ 每比特，不是线速。GATT 属性协议在 L2CAP 之上，相当于这个栈的「应用层」，不要用 HTTP 语义硬套。</p><p>不要把 BLE Mesh 写成 OSPF：受控洪泛与 TTL，规模小。</p><p><span class="marginnote">Core Spec 分 Controller/Host。802.15.1 曾把经典蓝牙收进 IEEE，工业以 SIG 为准。本课不把每个 Profile 列完。</span></p><h3 id="不是以太网桥" tabindex="-1">不是以太网桥 <a class="header-anchor" href="#不是以太网桥" aria-label="Permalink to &quot;不是以太网桥&quot;">​</a></h3><p>跳频 piconet 与广告间隔为电池服务。GATT 不要套 HTTP 语义。进 IP 要应用网关。与 Wi‑Fi 共存靠自适应跳频。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照：Wi‑Fi 关联 vs BLE 广告/连接；OFDM 宽信道 vs GFSK 窄信道。画：adv → connect → 间隔交换 → 休眠。与自协商对照：BLE 也交换能力，但是 GATT 服务发现。</p>',11)),(a(),s(d,null,{default:o(()=>[p(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20ADV%5B%22%E5%B9%BF%E5%91%8A%E4%BF%A1%E9%81%93%22%5D%20--%3E%20CON%5B%22%E8%BF%9E%E6%8E%A5%22%5D%0A%20%20CON%20--%3E%20INT%5B%22%E8%BF%9E%E6%8E%A5%E9%97%B4%E9%9A%94%22%5D%0A%20%20INT%20--%3E%20SLP%5B%22%E4%BC%91%E7%9C%A0%22%5D%0A%20%20HOP%5B%22%E8%B7%B3%E9%A2%91%22%5D%20--%3E%20INTF%5B%22%E9%81%BF%20Wi-Fi%20%E5%B9%B2%E6%89%B0%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[E(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>以太网 LLDP 发现交换机；BLE 发现外围设备。都是一跳身份，地址空间与安全模型不同（配对、LE Secure Connections）。不进 MAC 表，不跑 STP。若网关把 BLE 桥到 IP，那是应用网关，不是 802.1Q 桥。</p><p>共存：自适应跳频避开 Wi‑Fi 占用的信道，是频谱上的「线路码」式规避，不改香农公式。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 UWB 测距。蜂窝 RAN 与核心网是下一课。后课默认：蓝牙是短距跳频栈；BLE 为低功耗连接。</p><p>音频延迟与 BLE 吞吐上限来自间隔与 PHY 档（1M/2M/Coded），不要用千兆以太网对照当缺陷。</p><p>上一课留下的缺口在本课收口；「蓝牙与 BLE」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/cellular-ran-core">蜂窝：RAN 与核心网</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>经典蓝牙：跳频 piconet；BLE：广告+间隔休眠。</li><li>与 Wi‑Fi 共享 2.4 GHz，用跳频共存。</li><li>不是以太网桥，网关才进 IP。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：Bluetooth Core Spec；IEEE 802.15.1。</li></ul>',10))])}const m=r(c,[["render",h]]);export{f as __pageData,m as default};
